const sqlite3 = require('sqlite3').verbose();

const item = $input.first().json;

const signalMessageId = String(item.envelope?.timestamp || Date.now());
const testoOriginale = item.messageText || item.envelope?.dataMessage?.message || '';
const tipo = (item.attachments && item.attachments.length > 0) ? 'vocale' : 'testo';

// Calcola le date dei prossimi 7 giorni in Europe/Rome
const giorniSettimana = ['domenica','lunedi','martedi','mercoledi','giovedi','venerdi','sabato'];
const oggi = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
const mappaDate = {};
for (let i = 1; i <= 7; i++) {
  const d = new Date(oggi);
  d.setDate(oggi.getDate() + i);
  const nomeGiorno = giorniSettimana[d.getDay()];
  const anno = d.getFullYear();
  const mese = String(d.getMonth() + 1).padStart(2, '0');
  const giorno = String(d.getDate()).padStart(2, '0');
  mappaDate[nomeGiorno] = `${anno}-${mese}-${giorno}`;
}
const mappaDateStringa = Object.entries(mappaDate)
  .map(([g, d]) => `${g}=${d}`)
  .join(' ');

const isNuovo = await new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/data/segretario.db');
  db.run(
    `INSERT OR IGNORE INTO messages_inbox 
     (signal_message_id, testo_originale, tipo, stato_elaborazione) 
     VALUES (?, ?, ?, 'ricevuto')`,
    [signalMessageId, testoOriginale, tipo],
    function(err) {
      db.close();
      if (err) reject(err);
      else resolve(this.changes > 0);
    }
  );
});

return [{
  json: {
    signal_message_id: signalMessageId,
    testo_originale: testoOriginale,
    tipo: tipo,
    mittente: item.envelope?.source || '',
    nome_mittente: item.sourceName || '',
    is_nuovo: isNuovo,
    mappa_date: mappaDateStringa
  }
}];

