const response = $input.first().json;

const rawText = response.content[0].text;

const alfred = JSON.parse(rawText);

return [{
  json: {
    intent: alfred.intent,
    testo_risposta: alfred.testo_risposta,
    needs_confirmation: alfred.needs_confirmation,
    motivo_conferma: alfred.motivo_conferma || '',
    entita: alfred.entita || {}
  }
}];

const https = require('https');
const http = require('http');

const testo = $input.first().json.testo_risposta || $('Estrai JSON Alfred').item.json.testo_risposta;
const destinatario = $('Ricevi messaggio Signal').item.json.envelope.sourceNumber;

const payload = JSON.stringify({
  message: testo,
  number: "+393517872627",
  recipients: [destinatario]
});

await new Promise((resolve, reject) => {
  const options = {
    hostname: 'segretario_signal_cli',
    port: 8080,
    path: '/v2/send',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload)
    }
  };

  const req = http.request(options, (res) => {
    let data = '';
    res.on('data', chunk => data += chunk);
    res.on('end', () => {
      if (res.statusCode === 200 || res.statusCode === 201) {
        resolve(data);
      } else {
        reject(new Error(`Status ${res.statusCode}: ${data}`));
      }
    });
  });

  req.on('error', reject);
  req.write(payload);
  req.end();
});

return [{
  json: {
    messaggio_inviato: testo,
    destinatario: destinatario,
    stato: 'inviato'
  }
}];

const sqlite3 = require('sqlite3').verbose();

const inboxId = $('Salva in inbox').item.json.signal_message_id;
const testoRisposta = $('Estrai JSON Alfred').item.json.testo_risposta;
const intent = $('Estrai JSON Alfred').item.json.intent;

await new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/data/segretario.db');

  db.run(
    `INSERT INTO messages_outbox 
     (inbox_message_id, testo_risposta, tipo, azione_eseguita) 
     VALUES (?, ?, 'testo', ?)`,
    [inboxId, testoRisposta, intent],
    function(err) {
      db.close();
      if (err) reject(err);
      else resolve();
    }
  );
});

return [{
  json: {
    stato: 'completato',
    intent: intent,
    risposta_salvata: testoRisposta
  }
}];

const entita = $('Estrai JSON Alfred').item.json.entita;

const data = entita.data;
const ora = entita.ora;

const startDT = DateTime.fromISO(data, { zone: 'Europe/Rome' }).set({
  hour: parseInt(ora.split(':')[0]),
  minute: parseInt(ora.split(':')[1]),
  second: 0
});

const durataMinuti = parseInt(entita.durata_minuti) || 60;
const endDT = startDT.plus({ minutes: durataMinuti });

return [{
  json: {
    title: entita.descrizione,
    start: startDT.toFormat("yyyy-MM-dd'T'HH:mm:ss"),
    end: endDT.toFormat("yyyy-MM-dd'T'HH:mm:ss"),
    calendario: entita.calendario
  }
}];

// Recupera eventi Outlook salvati nel nodo intermedio
const eventiOutlook = $('Salva risultati Outlook').item.json.eventi_outlook || [];

// Recupera eventi Google dall'input corrente
const eventiGoogle = [];
const items = $input.all();

for (const item of items) {
  const data = item.json;

  // Nodo nativo Google Calendar — ogni evento è un item separato
  if (data.id && data.summary !== undefined) {
    eventiGoogle.push({
      titolo: data.summary || 'Senza titolo',
      inizio: data.start?.dateTime || data.start?.date || '',
      fine: data.end?.dateTime || data.end?.date || '',
      calendario: 'Google'
    });
  }

  // HTTP Request Google — risposta con campo "items"
  if (data.items && Array.isArray(data.items)) {
    for (const ev of data.items) {
      eventiGoogle.push({
        titolo: ev.summary || 'Senza titolo',
        inizio: ev.start?.dateTime || ev.start?.date || '',
        fine: ev.end?.dateTime || ev.end?.date || '',
        calendario: 'Google'
      });
    }
  }
}

const filtro = $('Estrai JSON Alfred').item.json.entita.filtro_calendario || 'entrambi';

let eventi = [];
if (filtro === 'outlook') {
  eventi = eventiOutlook;
} else if (filtro === 'google') {
  eventi = eventiGoogle;
} else {
  eventi = [...eventiOutlook, ...eventiGoogle];
}

eventi.sort((a, b) => new Date(a.inizio) - new Date(b.inizio));

const listaFormattata = eventi.map(ev => {
  const inizio = ev.inizio ? DateTime.fromISO(ev.inizio, { zone: 'Europe/Rome' }).toFormat('dd/MM HH:mm') : '';
  const fine = ev.fine ? DateTime.fromISO(ev.fine, { zone: 'Europe/Rome' }).toFormat('HH:mm') : '';
  return `• ${inizio}-${fine} [${ev.calendario}] ${ev.titolo}`;
}).join('\n');

const testo = eventi.length > 0
  ? `Ecco i tuoi appuntamenti:\n${listaFormattata}`
  : 'Non ho trovato appuntamenti nel periodo richiesto.';

return [{
  json: {
    testo_risposta: testo
  }
}];

const entita = $('Estrai JSON Alfred').item.json.entita;

return [{
  json: {
    data_inizio: entita.data_inizio,
    data_fine: entita.data_fine,
    filtro_calendario: entita.filtro_calendario || 'entrambi',
    timeMin: entita.data_inizio + 'T00:00:00Z',
    timeMax: entita.data_fine + 'T23:59:59Z'
  }
}];

const outlookData = $input.first().json;
const eventi = [];

if (outlookData.value && Array.isArray(outlookData.value)) {
  for (const ev of outlookData.value) {
    eventi.push({
      titolo: ev.subject || 'Senza titolo',
      inizio: ev.start?.dateTime || '',
      fine: ev.end?.dateTime || '',
      calendario: 'Outlook'
    });
  }
}

return [{
  json: {
    eventi_outlook: eventi
  }
}];

const sqlite3 = require('sqlite3').verbose();

const entita = $('Estrai JSON Alfred').item.json.entita;
const sourceMessageId = $('Salva in inbox').item.json.signal_message_id;

const descrizione = entita.descrizione || '';
const scadenza = entita.scadenza || null;
const priorita = entita.priorita || 'media';

// Calcola next_followup_at: se c'è scadenza usa quella, altrimenti domani
const oggi = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Rome' }));
let nextFollowup;
if (scadenza) {
  nextFollowup = scadenza + 'T09:00:00';
} else {
  const domani = new Date(oggi);
  domani.setDate(oggi.getDate() + 1);
  const anno = domani.getFullYear();
  const mese = String(domani.getMonth() + 1).padStart(2, '0');
  const giorno = String(domani.getDate()).padStart(2, '0');
  nextFollowup = `${anno}-${mese}-${giorno}T09:00:00`;
}

await new Promise((resolve, reject) => {
  const db = new sqlite3.Database('/data/segretario.db');
  db.run(
    `INSERT INTO task 
     (descrizione, scadenza, priorita, stato, reminder_count, next_followup_at, source_message_id, creato_il, updated_at)
     VALUES (?, ?, ?, 'aperto', 0, ?, ?, datetime('now'), datetime('now'))`,
    [descrizione, scadenza, priorita, nextFollowup, sourceMessageId],
    function(err) {
      db.close();
      if (err) reject(err);
      else resolve(this.lastID);
    }
  );
});

return [{
  json: {
    testo_risposta: $('Estrai JSON Alfred').item.json.testo_risposta
  }
}];
